black_plague_scenario_seed_state = {
	black_plague_ensure_current_state_values = yes
	if = {
		limit = { has_state_flag = black_plague_scenario_seeded }
		set_temp_variable = { black_plague_scenario_state_was_seeded = constant:black_plague_value.one }
	}
	else = {
		set_temp_variable = { black_plague_scenario_state_was_seeded = constant:black_plague_value.zero }
		set_variable = { black_plague_provenance = constant:black_plague_provenance.natural }
		set_variable = { black_plague_load = constant:black_plague_evolution_runtime.scenario_seed_load }
		set_variable = { black_plague_mortality_pressure = constant:black_plague_evolution_runtime.scenario_seed_mortality }
		set_variable = { black_plague_spread_pressure = constant:black_plague_evolution_runtime.scenario_seed_spread }
		set_variable = { black_plague_containment = constant:black_plague_evolution_runtime.scenario_seed_containment }
		set_variable = { black_plague_treatment_coverage = constant:black_plague_evolution_runtime.scenario_seed_treatment }
		set_variable = { black_plague_relapse_risk = constant:black_plague_evolution_runtime.scenario_seed_relapse }
		set_variable = { black_plague_rat_infestation = constant:black_plague_evolution_runtime.scenario_seed_infestation }
		set_variable = { black_plague_incoming_exposure = constant:black_plague_value.zero }
		set_temp_variable = { black_plague_scenario_seed_phase = constant:black_plague_phase.infected }
		if = {
			limit = { check_variable = { global.black_plague_scenario_intensity = constant:triggerable_scenario_intensity.medium } }
			set_temp_variable = { black_plague_scenario_seed_phase = constant:black_plague_phase.severe_crisis }
		}
		else_if = {
			limit = { check_variable = { global.black_plague_scenario_intensity > constant:triggerable_scenario_intensity.medium } }
			set_temp_variable = { black_plague_scenario_seed_phase = constant:black_plague_phase.severe_crisis }
		}
		if = {
			limit = {
				has_state_flag = black_plague_scenario_anchor
				check_variable = { global.black_plague_scenario_intensity = constant:triggerable_scenario_intensity.maximum }
			}
			set_temp_variable = { black_plague_scenario_seed_phase = constant:black_plague_phase.collapsed }
		}
		set_temp_variable = { black_plague_next_phase = black_plague_scenario_seed_phase }
		black_plague_set_current_state_phase = yes
		set_state_flag = black_plague_scenario_seeded
	}
	if = {
		limit = {
			black_plague_state_is_infected_or_worse = yes
			NOT = { is_in_array = { array = global.black_plague_scenario_rat_candidate_states value = THIS } }
		}
		set_state_flag = black_plague_scenario_rat_candidate
		add_to_array = { array = global.black_plague_scenario_rat_candidate_states value = THIS }
	}
	if = {
		limit = {
			check_variable = { global.black_plague_scenario_rat_candidate_states^num = constant:black_plague_value.zero }
			RTA = { exists = yes NOT = { has_country_flag = black_plague_rat_country } }
		}
		set_state_flag = black_plague_scenario_rat_candidate
		add_to_array = { array = global.black_plague_scenario_rat_candidate_states value = THIS }
	}
	if = {
		limit = { NOT = { has_state_flag = black_plague_scenario_opening_deaths_applied } }
		set_temp_variable = { black_plague_scenario_opening_state_deaths = global.black_plague_scenario_opening_deaths_remaining }
		divide_temp_variable = { black_plague_scenario_opening_state_deaths = global.black_plague_scenario_established_target }
		clamp_temp_variable = { var = black_plague_scenario_opening_state_deaths min = constant:black_plague_scenario.opening_deaths_minimum_remaining }
		set_temp_variable = { state_civilian_population_loss_requested = black_plague_scenario_opening_state_deaths }
		set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:black_plague_scenario.opening_population_floor }
		multiply_temp_variable = { state_civilian_population_loss_minimum_remaining = state_population_k }
		multiply_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:black_plague_value.people_per_thousand }
		set_temp_variable = { state_civilian_population_loss_reason = constant:chaos_meter_deaths_reason.black_plague }
		set_temp_variable = { state_civilian_population_loss_log_deaths = constant:black_plague_value.one }
		set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
		set_temp_variable = { state_civilian_population_loss_has_target_country = constant:black_plague_value.one }
		set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:black_plague_value.one }
		apply_exact_state_civilian_population_loss = yes
		if = {
			limit = { check_variable = { state_civilian_population_loss_applied > constant:black_plague_value.zero } }
			add_to_variable = { global.black_plague_deaths_total = state_civilian_population_loss_applied }
			subtract_from_variable = { global.black_plague_scenario_opening_deaths_remaining = state_civilian_population_loss_applied }
		}
		set_state_flag = black_plague_scenario_opening_deaths_applied
	}
	black_plague_register_current_state = yes
	if = {
		limit = {
			check_variable = {
				var = black_plague_scenario_state_was_seeded
				value = constant:black_plague_value.zero
				compare = equals
			}
		}
		add_to_variable = { global.black_plague_scenario_seeded_states = constant:black_plague_value.one }
	}
	every_neighbor_state = {
		limit = {
			black_plague_scenario_valid_human_state = yes
			NOT = { has_state_flag = black_plague_scenario_seeded }
			NOT = { has_state_flag = black_plague_established_infection }
		}
		black_plague_ensure_current_state_values = yes
		set_variable = { black_plague_incoming_exposure = constant:black_plague_scenario.outer_ring_exposure }
		set_variable = { black_plague_provenance = constant:black_plague_provenance.natural }
		set_temp_variable = { black_plague_next_phase = constant:black_plague_phase.threatened }
		black_plague_set_current_state_phase = yes
		black_plague_register_current_state = yes
	}
}

riches_found_apply_harm_record = {
	if = {
		limit = {
			has_variable = riches_found_harm_deaths
			check_variable = { var = riches_found_harm_deaths value = constant:riches_found_value.zero compare = greater_than }
		}
		if = {
			limit = { NOT = { has_variable = riches_found_harm_condemnation } }
			set_temp_variable = { riches_found_harm_condemnation = constant:riches_found_value.zero }
		}
		if = {
			limit = { NOT = { has_variable = riches_found_harm_context } }
			set_temp_variable = { riches_found_harm_context = constant:condemnation_context.camp_operation }
		}
		if = {
			limit = { OWNER = { exists = yes } }
			OWNER = { save_event_target_as = riches_found_harm_victim }
		}
		set_temp_variable = { state_civilian_population_loss_requested = riches_found_harm_deaths }
		set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:riches_found_value.zero }
		set_temp_variable = { state_civilian_population_loss_log_deaths = constant:riches_found_value.one }
		set_temp_variable = { state_civilian_population_loss_reason = constant:chaos_meter_deaths_reason.resource_field_incident }
		set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
		set_temp_variable = { state_civilian_population_loss_has_target_country = constant:riches_found_value.one }
		set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:riches_found_value.one }
		apply_exact_state_civilian_population_loss = yes
		set_variable = { riches_found_harm_applied = state_civilian_population_loss_applied }
		if = {
			limit = { NOT = { has_variable = riches_found_harm_total_deaths } }
			set_variable = { riches_found_harm_total_deaths = constant:riches_found_value.zero }
		}
		add_to_variable = { riches_found_harm_total_deaths = riches_found_harm_applied }
		set_state_flag = riches_found_harm_occurred
		if = {
			limit = {
				check_variable = {
					var = riches_found_harm_applied
					value = constant:riches_found_harm.mass_death_gate
					compare = greater_than_or_equals
				}
			}
			set_state_flag = riches_found_mass_death_occurred
			if = {
				limit = { CONTROLLER = { exists = yes } }
				CONTROLLER = { set_country_flag = riches_found_mass_death_occurred }
			}
		}
		set_temp_variable = { riches_found_harm_severity = constant:condemnation_severity.major }
		if = {
			limit = {
				check_variable = {
					var = riches_found_harm_applied
					value = constant:riches_found_harm.mass_death_gate
					compare = greater_than_or_equals
				}
			}
			set_temp_variable = { riches_found_harm_severity = constant:condemnation_severity.mass_death }
		}
		if = {
			limit = {
				check_variable = { var = riches_found_harm_applied value = constant:riches_found_value.zero compare = greater_than }
				CONTROLLER = { exists = yes }
			}
			CONTROLLER = {
				set_temp_variable = { condemnation_source_type = constant:condemnation_source.atrocity }
				set_temp_variable = { condemnation_base_gain = riches_found_harm_condemnation }
				set_temp_variable = { condemnation_visibility_type = constant:condemnation_visibility.public }
				set_temp_variable = { condemnation_severity_type = riches_found_harm_severity }
				set_temp_variable = { condemnation_civilian_deaths = riches_found_harm_applied }
				set_temp_variable = { condemnation_contamination_value = constant:riches_found_value.zero }
				set_temp_variable = { condemnation_context_type = riches_found_harm_context }
				if = {
					limit = { has_event_target = riches_found_harm_victim }
					set_temp_variable = { condemnation_victim_country = event_target:riches_found_harm_victim }
				}
				condemnation_add_source = yes
			}
		}
	}
}

famine_apply_related_state_deaths_exact = {
	set_temp_variable = { famine_related_deaths_applied = constant:humanitarian_population.zero }
	set_temp_variable = { famine_adapter_amount = humanitarian_related_deaths_requested }
	famine_validate_state_local_food_receipt_exact = yes
	if = {
		limit = {
			check_variable = { humanitarian_related_deaths_request_proven > constant:humanitarian_runtime.zero }
			check_variable = { humanitarian_related_deaths_requested > constant:humanitarian_population.zero }
			check_variable = { famine_adapter_contract_valid = constant:humanitarian_runtime.one }
			OR = {
				check_variable = { humanitarian_related_deaths_reason = constant:chaos_meter_deaths_reason.occupation_repression }
				check_variable = { humanitarian_related_deaths_reason = constant:chaos_meter_deaths_reason.forced_labor }
			}
		}
		set_temp_variable = { state_civilian_population_loss_requested = humanitarian_related_deaths_requested }
		set_temp_variable = { state_civilian_population_loss_reason = humanitarian_related_deaths_reason }
		set_temp_variable = { state_civilian_population_loss_log_deaths = constant:chaos_meter_deaths.one }
		set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
		set_temp_variable = { state_civilian_population_loss_has_target_country = constant:chaos_meter_deaths.one }
		set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:chaos_meter_deaths.one }
		if = {
			limit = { check_variable = { humanitarian_related_deaths_minimum_remaining > constant:humanitarian_population.zero } }
			set_temp_variable = { state_civilian_population_loss_minimum_remaining = humanitarian_related_deaths_minimum_remaining }
		}
		apply_exact_state_civilian_population_loss = yes
		set_temp_variable = { famine_related_deaths_applied = state_civilian_population_loss_applied }
	}
	set_temp_variable = { humanitarian_related_deaths_request_proven = constant:humanitarian_runtime.zero }
	set_temp_variable = { humanitarian_related_deaths_requested = constant:humanitarian_population.zero }
	set_temp_variable = { humanitarian_related_deaths_minimum_remaining = constant:humanitarian_population.zero }
	set_temp_variable = { humanitarian_related_deaths_reason = constant:chaos_meter_deaths_reason.unknown }
	famine_clear_state_local_food_receipt = yes
}

famine_apply_mortality = {
	set_temp_variable = { famine_mortality_result = constant:humanitarian_population.zero }
	if = {
		limit = {
			famine_food_stage_requires_mortality = yes
			check_variable = { var = famine_food_next_mortality_date value = global.date compare = less_than_or_equals }
		}
		famine_initialize_state = yes
		set_temp_variable = { famine_mortality_minimum_exposure = constant:famine_mortality.acute_shortage_minimum_exposure_days }
		set_temp_variable = { famine_mortality_interval = constant:famine_mortality.acute_shortage_interval_days }
		set_temp_variable = { famine_mortality_rate = constant:famine_mortality.acute_shortage_rate }
		if = {
			limit = { check_variable = { var = famine_food_stage value = constant:famine_food_stage.famine   compare = equals } }
			set_temp_variable = { famine_mortality_minimum_exposure = constant:famine_mortality.famine_minimum_exposure_days }
			set_temp_variable = { famine_mortality_interval = constant:famine_mortality.famine_interval_days }
			set_temp_variable = { famine_mortality_rate = constant:famine_mortality.famine_rate }
		}
		if = {
			limit = { check_variable = { var = famine_food_stage value = constant:famine_food_stage.catastrophic_famine   compare = equals } }
			set_temp_variable = { famine_mortality_minimum_exposure = constant:famine_mortality.catastrophic_minimum_exposure_days }
			set_temp_variable = { famine_mortality_interval = constant:famine_mortality.catastrophic_interval_days }
			set_temp_variable = { famine_mortality_rate = constant:famine_mortality.catastrophic_rate }
		}
		if = {
			limit = { check_variable = { var = famine_food_exposure_days value = famine_mortality_minimum_exposure compare = greater_than_or_equals } }
			set_temp_variable = { famine_mortality_population = state_population_k }
			multiply_temp_variable = { famine_mortality_population = constant:chaos_meter_deaths.people_per_k }
			round_temp_variable = famine_mortality_population
			set_temp_variable = { famine_mortality_floor = famine_mortality_population }
			multiply_temp_variable = { famine_mortality_floor = constant:famine_mortality.protected_floor_share }
			round_temp_variable = famine_mortality_floor
			if = {
				limit = { check_variable = { var = famine_mortality_floor value = constant:famine_mortality.protected_floor_people compare = less_than } }
				set_temp_variable = { famine_mortality_floor = constant:famine_mortality.protected_floor_people }
			}
			clamp_temp_variable = {
				var = famine_mortality_floor
				min = constant:humanitarian_population.zero
				max = famine_mortality_population
			}
			set_temp_variable = { famine_mortality_available = famine_mortality_population }
			subtract_from_temp_variable = { famine_mortality_available = famine_mortality_floor }
			clamp_temp_variable = { var = famine_mortality_available min = constant:humanitarian_population.zero }

			set_temp_variable = { famine_mortality_exposure_factor = famine_food_exposure_days }
			multiply_temp_variable = { famine_mortality_exposure_factor = constant:famine_mortality.exposure_multiplier_per_day }
			add_to_temp_variable = { famine_mortality_exposure_factor = constant:famine_mortality.minimum_exposure_multiplier }
			clamp_temp_variable = {
				var = famine_mortality_exposure_factor
				min = constant:famine_mortality.minimum_exposure_multiplier
				max = constant:famine_mortality.maximum_exposure_multiplier
			}

			set_temp_variable = { famine_mortality_vulnerability_factor = constant:famine_food_weight.component_factor_base }
		set_temp_variable = { famine_mortality_component_factor = famine_component_vulnerability }
		divide_temp_variable = { famine_mortality_component_factor = constant:famine_food_component.component_scale }
		add_to_temp_variable = { famine_mortality_vulnerability_factor = famine_mortality_component_factor }
			set_temp_variable = { famine_mortality_access_factor = constant:famine_food_weight.component_factor_base }
			set_temp_variable = { famine_mortality_component_factor = famine_component_transport }
			multiply_temp_variable = { famine_mortality_component_factor = constant:famine_mortality.access_transport_share }
			set_temp_variable = { famine_mortality_need_factor = famine_component_need }
			multiply_temp_variable = { famine_mortality_need_factor = constant:famine_mortality.access_need_share }
			add_to_temp_variable = { famine_mortality_component_factor = famine_mortality_need_factor }
			divide_temp_variable = { famine_mortality_component_factor = constant:famine_food_component.component_scale }
			add_to_temp_variable = { famine_mortality_access_factor = famine_mortality_component_factor }
			set_temp_variable = { famine_mortality_policy_factor = constant:famine_food_weight.component_factor_base }
			set_temp_variable = { famine_mortality_component_factor = famine_component_extraction }
			divide_temp_variable = { famine_mortality_component_factor = constant:famine_food_component.component_scale }
			add_to_temp_variable = { famine_mortality_policy_factor = famine_mortality_component_factor }
			set_temp_variable = { famine_mortality_environment_factor = constant:famine_food_weight.component_factor_base }
			set_temp_variable = { famine_mortality_component_factor = famine_component_environment }
			divide_temp_variable = { famine_mortality_component_factor = constant:famine_food_component.component_scale }
			add_to_temp_variable = { famine_mortality_environment_factor = famine_mortality_component_factor }
			set_temp_variable = { famine_mortality_governance_factor = constant:famine_food_weight.component_factor_base }
			set_temp_variable = { famine_mortality_component_factor = famine_component_governance }
			divide_temp_variable = { famine_mortality_component_factor = constant:famine_food_component.component_scale }
			add_to_temp_variable = { famine_mortality_governance_factor = famine_mortality_component_factor }
			set_temp_variable = { famine_mortality_relief_factor = constant:famine_food_weight.component_factor_base }
			set_temp_variable = { famine_mortality_component_factor = famine_component_relief }
			divide_temp_variable = { famine_mortality_component_factor = constant:famine_food_component.component_scale }
			subtract_from_temp_variable = { famine_mortality_relief_factor = famine_mortality_component_factor }
			clamp_temp_variable = {
				var = famine_mortality_relief_factor
				min = constant:famine_mortality.minimum_relief_factor
				max = constant:famine_mortality.maximum_relief_factor
			}

			set_temp_variable = { famine_mortality_request = famine_mortality_population }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_rate }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_exposure_factor }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_vulnerability_factor }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_access_factor }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_policy_factor }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_environment_factor }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_governance_factor }
			multiply_temp_variable = { famine_mortality_request = famine_mortality_relief_factor }
			clamp_temp_variable = {
				var = famine_mortality_request
				min = constant:humanitarian_population.zero
				max = famine_mortality_available
			}
			round_temp_variable = famine_mortality_request
			if = {
				limit = { check_variable = { var = famine_mortality_request value = constant:famine_mortality.minimum_pulse_people compare = greater_than_or_equals } }
				set_temp_variable = { state_civilian_population_loss_requested = famine_mortality_request }
				set_temp_variable = { state_civilian_population_loss_minimum_remaining = famine_mortality_floor }
				set_temp_variable = { state_civilian_population_loss_reason = constant:chaos_meter_deaths_reason.famine }
				set_temp_variable = { state_civilian_population_loss_log_deaths = constant:chaos_meter_deaths.one }
				set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
				set_temp_variable = { state_civilian_population_loss_has_target_country = constant:chaos_meter_deaths.one }
				set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:chaos_meter_deaths.one }
				apply_exact_state_civilian_population_loss = yes
				set_variable = { famine_last_deaths_applied = state_civilian_population_loss_applied }
				add_to_variable = { famine_total_deaths = state_civilian_population_loss_applied }
				set_temp_variable = { famine_mortality_result = state_civilian_population_loss_applied }
				famine_record_exact_mortality_condemnation = yes
			}
			set_variable = { famine_food_next_mortality_date = global.date }
			add_to_variable = { famine_food_next_mortality_date = famine_mortality_interval }
		}
	}
}

migration_apply_related_state_deaths_exact = {
	set_temp_variable = { migration_related_deaths_applied = constant:humanitarian_population.zero }
	if = {
		limit = {
			humanitarian_state_is_valid = yes
			check_variable = { migration_related_deaths_request_proven > constant:humanitarian_runtime.zero }
			check_variable = { migration_related_deaths_requested > constant:humanitarian_population.zero }
			check_variable = { migration_related_deaths_cohort_id > constant:humanitarian_runtime.zero }
			check_variable = { migration_related_deaths_route_proven > constant:humanitarian_runtime.zero }
			check_variable = { migration_related_deaths_actor_proven > constant:humanitarian_runtime.zero }
			check_variable = { migration_related_deaths_generation > constant:humanitarian_runtime.zero }
			check_variable = { migration_related_deaths_revision > constant:humanitarian_runtime.zero }
			check_variable = { migration_related_deaths_request_id > constant:humanitarian_runtime.zero }
			has_event_target = migration_related_deaths_actor
			event_target:migration_related_deaths_actor = { humanitarian_country_is_valid = yes }
			check_variable = { migration_related_deaths_reason = constant:chaos_meter_deaths_reason.forced_displacement }
		}
		set_temp_variable = { state_civilian_population_loss_requested = migration_related_deaths_requested }
		set_temp_variable = { state_civilian_population_loss_reason = migration_related_deaths_reason }
		set_temp_variable = { state_civilian_population_loss_log_deaths = constant:chaos_meter_deaths.one }
		set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
		set_temp_variable = { state_civilian_population_loss_has_target_country = constant:chaos_meter_deaths.one }
		set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:chaos_meter_deaths.one }
		apply_exact_state_civilian_population_loss = yes
		set_temp_variable = { migration_related_deaths_applied = state_civilian_population_loss_applied }
	}
	set_temp_variable = { migration_related_deaths_request_proven = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_requested = constant:humanitarian_population.zero }
	set_temp_variable = { migration_related_deaths_cohort_id = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_route_proven = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_actor_proven = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_generation = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_revision = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_request_id = constant:humanitarian_runtime.zero }
	set_temp_variable = { migration_related_deaths_reason = constant:chaos_meter_deaths_reason.unknown }
}

fallout_event_230_apply_movement_shares = {
