		}
		set_variable = { fallout_event_243_deaths_applied_count = constant:fallout_event_runtime.zero }
		var:fallout_event_243_transformer_state_id = {
			set_temp_variable = { fallout_event_243_death_request = state_population_k }
			multiply_temp_variable = { fallout_event_243_death_request = constant:chaos_meter_deaths.people_per_k }
			if = {
				limit = { check_variable = { ROOT.fallout_event_243_selected_branch = constant:fallout_event_243_branch.cannibalize_industrial_line } }
				multiply_temp_variable = { fallout_event_243_death_request = constant:fallout_event_243_threshold.industry_failure_death_percent }
			}
			else_if = {
				limit = { check_variable = { ROOT.fallout_event_243_selected_branch = constant:fallout_event_243_branch.protect_hospital_power } }
				multiply_temp_variable = { fallout_event_243_death_request = constant:fallout_event_243_threshold.hospital_failure_death_percent }
			}
			else_if = {
				limit = { check_variable = { ROOT.fallout_event_243_selected_branch = constant:fallout_event_243_branch.decentralize_microgrids } }
				multiply_temp_variable = { fallout_event_243_death_request = constant:fallout_event_243_threshold.microgrid_failure_death_percent }
			}
			else = { multiply_temp_variable = { fallout_event_243_death_request = constant:fallout_event_243_threshold.neighbor_failure_death_percent } }
			round_temp_variable = fallout_event_243_death_request
			set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:fallout_event_runtime.one }
			set_temp_variable = { state_civilian_population_loss_requested = fallout_event_243_death_request }
			set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:fallout_event_243_threshold.minimum_remaining_people }
