			set_temp_variable = { state_civilian_population_loss_log_deaths = constant:fallout_event_runtime.zero }
			set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
			set_temp_variable = { state_civilian_population_loss_has_target_country = constant:fallout_event_runtime.one }
			apply_exact_state_civilian_population_loss = yes
			set_variable = { ROOT.fallout_event_243_deaths_applied_count = state_civilian_population_loss_applied }
			if = {
				limit = {
					check_variable = { var = ROOT.fallout_event_243_failure_damage_applied value = constant:fallout_event_runtime.zero compare = equals }
					check_variable = { var = non_damaged_building_level@infrastructure value = constant:fallout_event_runtime.zero compare = greater_than }
					OR = {
						check_variable = { ROOT.fallout_event_243_selected_branch = constant:fallout_event_243_branch.cannibalize_industrial_line }
						check_variable = { ROOT.fallout_event_243_selected_branch = constant:fallout_event_243_branch.decentralize_microgrids }
					}
				}
				if = {
					limit = { check_variable = { ROOT.fallout_event_243_selected_branch = constant:fallout_event_243_branch.cannibalize_industrial_line } }
