fallout_event_499_apply_migration = {
	set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_499_threshold.result_migration_share_failure }
	if = { limit = { check_variable = { fallout_event_499_result_outcome = constant:fallout_event_outcome_type.success } } set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_499_threshold.result_migration_share_success } }
	else_if = { limit = { check_variable = { fallout_event_499_result_outcome = constant:fallout_event_outcome_type.partial } } set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_499_threshold.result_migration_share_partial } }
	if = { limit = { check_variable = { fallout_event_499_history_stage = constant:fallout_event_runtime.two } } set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_499_threshold.callback_migration_share_failure } }
	if = { limit = { check_variable = { fallout_event_499_history_stage = constant:fallout_event_runtime.two } check_variable = { fallout_event_499_result_outcome = constant:fallout_event_outcome_type.success } } set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_499_threshold.callback_migration_share_success } }
	else_if = { limit = { check_variable = { fallout_event_499_history_stage = constant:fallout_event_runtime.two } check_variable = { fallout_event_499_result_outcome = constant:fallout_event_outcome_type.partial } } set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_499_threshold.callback_migration_share_partial } }
	if = { limit = { NOT = { check_variable = { fallout_event_499_selected_branch = constant:fallout_event_499_branch.escort_clean_ice_families } } } set_temp_variable = { fallout_event_499_migration_share = constant:fallout_event_runtime.zero } }
	set_variable = { fallout_event_499_migration_applied = constant:fallout_event_runtime.zero }
	var:fallout_event_499_origin_state_id = {
		if = {
			limit = { check_variable = { var = state_population_k value = constant:fallout_event_runtime.zero compare = greater_than } }
			set_temp_variable = { fallout_event_499_migration_requested = state_population_k }
			multiply_temp_variable = { fallout_event_499_migration_requested = constant:chaos_meter_deaths.people_per_k }
			multiply_temp_variable = { fallout_event_499_migration_requested = fallout_event_499_migration_share }
			round_temp_variable = fallout_event_499_migration_requested
			clamp_temp_variable = { var = fallout_event_499_migration_requested min = constant:fallout_event_runtime.zero max = state_population_k }
			set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:fallout_event_runtime.one }
			set_temp_variable = { state_civilian_population_loss_requested = fallout_event_499_migration_requested }
			set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:fallout_event_499_threshold.minimum_remaining_people }
			set_temp_variable = { state_civilian_population_loss_reason = constant:chaos_meter_deaths_reason.fallout_aftermath }
			set_temp_variable = { state_civilian_population_loss_log_deaths = constant:fallout_event_runtime.zero }
			set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
			set_temp_variable = { state_civilian_population_loss_has_target_country = constant:fallout_event_runtime.one }
			apply_exact_state_civilian_population_loss = yes
			set_variable = { ROOT.fallout_event_499_migration_applied = state_civilian_population_loss_applied }
			set_temp_variable = { fallout_event_499_migration_requested = 0 }
		}
	}
	if = {
		limit = { check_variable = { var = fallout_event_499_migration_applied value = constant:fallout_event_499_threshold.minimum_migration_people compare = greater_than_or_equals } }
		var:fallout_event_499_target_state_id = {
			if = { limit = { NOT = { has_variable = fallout_state_refugee_arrivals_current } } set_variable = { fallout_state_refugee_arrivals_current = constant:fallout_event_runtime.zero } }
			add_to_variable = { fallout_state_refugee_arrivals_current = ROOT.fallout_event_499_migration_applied }
			add_manpower = var:ROOT.fallout_event_499_migration_applied
			set_variable = { fallout_event_499_last_migration_arrivals = ROOT.fallout_event_499_migration_applied }
			set_state_flag = fallout_event_499_memory_migration_arrivals
		}
		var:fallout_event_499_origin_state_id = {
			if = { limit = { NOT = { has_variable = fallout_state_refugee_departures_current } } set_variable = { fallout_state_refugee_departures_current = constant:fallout_event_runtime.zero } }
			add_to_variable = { fallout_state_refugee_departures_current = ROOT.fallout_event_499_migration_applied }
			set_variable = { fallout_event_499_last_migration_departures = ROOT.fallout_event_499_migration_applied }
			set_state_flag = fallout_event_499_memory_migration_departures
		}
		add_to_variable = { fallout_ravine_migration_arrivals_current = fallout_event_499_migration_applied }
		add_to_variable = { fallout_ravine_migration_departures_current = fallout_event_499_migration_applied }
		set_country_flag = fallout_ravine_migration_route_open
	}
	else = {
		set_variable = { fallout_event_499_last_migration_arrivals = constant:fallout_event_runtime.zero }
		set_variable = { fallout_event_499_last_migration_departures = constant:fallout_event_runtime.zero }
	}
	clear_variable = fallout_event_499_migration_applied
	set_temp_variable = { fallout_event_499_migration_share = 0 }
}

air_winter_apply_state_population_loss = {
	set_temp_variable = { air_winter_death_percent = constant:air_winter_runtime.zero }
	set_variable = { air_winter_expected_monthly_death_percent = constant:air_winter_runtime.zero }
	if = { limit = { air_winter_is_phase_3 = yes } set_temp_variable = { air_winter_death_percent = constant:air_winter_deaths.phase_3_percent } }
	else_if = { limit = { air_winter_is_phase_4 = yes } set_temp_variable = { air_winter_death_percent = constant:air_winter_deaths.phase_4_percent } }
	else_if = { limit = { air_winter_is_phase_5 = yes } set_temp_variable = { air_winter_death_percent = constant:air_winter_deaths.phase_5_percent } }
	else_if = { limit = { air_winter_is_phase_6 = yes } set_temp_variable = { air_winter_death_percent = constant:air_winter_deaths.phase_6_percent } }

	if = {
		limit = {
			air_winter_system_enabled = yes
			check_variable = { air_winter_death_percent > constant:air_winter_runtime.zero }
			check_variable = { state_population_k > constant:air_winter_runtime.zero }
		}
		set_temp_variable = { air_winter_death_multiplier = constant:air_winter_runtime.one }
		set_temp_variable = { air_winter_death_exposure_multiplier = air_winter_exposure }
		multiply_temp_variable = { air_winter_death_exposure_multiplier = constant:air_winter_deaths.exposure_multiplier_per_point }
		add_to_temp_variable = { air_winter_death_multiplier = air_winter_death_exposure_multiplier }
		if = { limit = { air_winter_has_low_food = yes } multiply_temp_variable = { air_winter_death_multiplier = constant:air_winter_deaths.low_food_multiplier } }
		if = { limit = { air_winter_has_low_shelter = yes } multiply_temp_variable = { air_winter_death_multiplier = constant:air_winter_deaths.low_shelter_multiplier } }
		if = {
			limit = { infrastructure < constant:air_winter_pressure.low_infrastructure_level }
			multiply_temp_variable = { air_winter_death_multiplier = constant:air_winter_deaths.low_infrastructure_multiplier }
		}
		if = {
			limit = { NOT = { is_owned_and_controlled_by = OWNER } }
			multiply_temp_variable = { air_winter_death_multiplier = constant:air_winter_deaths.occupation_multiplier }
		}

		set_temp_variable = { air_winter_death_adaptation_multiplier = air_winter_adaptation }
		multiply_temp_variable = { air_winter_death_adaptation_multiplier = constant:air_winter_deaths.adaptation_reduction_per_point }
		set_temp_variable = { air_winter_death_adaptation_remaining = constant:air_winter_runtime.one }
		subtract_from_temp_variable = { air_winter_death_adaptation_remaining = air_winter_death_adaptation_multiplier }
		clamp_temp_variable = {
			var = air_winter_death_adaptation_remaining
			min = constant:air_winter_deaths.minimum_multiplier
			max = constant:air_winter_runtime.one
		}
		multiply_temp_variable = { air_winter_death_multiplier = air_winter_death_adaptation_remaining }
		clamp_temp_variable = {
			var = air_winter_death_multiplier
			min = constant:air_winter_deaths.minimum_multiplier
			max = constant:air_winter_deaths.maximum_multiplier
		}
		multiply_temp_variable = { air_winter_death_percent = air_winter_death_multiplier }
		if = {
			limit = { has_state_flag = air_winter_memory_tunnel_school_protection }
			multiply_temp_variable = { air_winter_death_percent = constant:air_winter_deaths.tunnel_school_protection_multiplier }
		}
		clamp_temp_variable = {
			var = air_winter_death_percent
			min = constant:air_winter_runtime.zero
			max = constant:air_winter_deaths.maximum_monthly_percent
		}
		set_variable = { air_winter_expected_monthly_death_percent = air_winter_death_percent }

		set_temp_variable = { chaos_deaths_change = state_population_k }
		multiply_temp_variable = { chaos_deaths_change = air_winter_death_percent }
		multiply_temp_variable = { chaos_deaths_change = constant:air_winter_deaths.population_scale }
		round_temp_variable = chaos_deaths_change
		set_temp_variable = { air_winter_state_population_exact = state_population_k }
		multiply_temp_variable = { air_winter_state_population_exact = constant:air_winter_deaths.population_scale }
		clamp_temp_variable = {
			var = chaos_deaths_change
			min = constant:air_winter_runtime.zero
			max = air_winter_state_population_exact
		}

		if = {
			limit = {
				check_variable = { chaos_deaths_change > constant:air_winter_runtime.zero }
				NOT = { has_global_flag = settings_chaos_deaths_disabled }
			}
			set_temp_variable = { state_civilian_population_loss_requested = chaos_deaths_change }
			set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:air_winter_runtime.zero }
			set_temp_variable = { state_civilian_population_loss_log_deaths = constant:air_winter_runtime.one }
			set_temp_variable = { state_civilian_population_loss_reason = constant:chaos_meter_deaths_reason.air_winter_exposure }
			set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
			set_temp_variable = { state_civilian_population_loss_has_target_country = constant:air_winter_runtime.one }
			set_temp_variable = { state_civilian_population_loss_applied = constant:air_winter_runtime.zero }
			set_temp_variable = { state_civilian_population_loss_result = constant:air_winter_runtime.zero }
			set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:air_winter_runtime.one }
			apply_exact_state_civilian_population_loss = yes
			if = {
				limit = { check_variable = { state_civilian_population_loss_applied > constant:air_winter_runtime.zero } }
				add_to_variable = { air_winter_population_loss_memory = state_civilian_population_loss_applied }
				# Supply the exact Air Cleanliness/winter receipt. These values are
				# source-owned state ledgers from this cycle; the adapter does not
				# infer food, environment, route, policy, or identity from deaths.
				OWNER = { save_event_target_as = famine_adapter_actor }
				set_temp_variable = { famine_adapter_state_proven = THIS.id }
				set_temp_variable = { famine_adapter_food_proven = air_winter_phase }
				set_temp_variable = { famine_adapter_environment_proven = air_winter_phase }
				set_temp_variable = { famine_adapter_transport_proven = air_winter_shelter_capacity }
				set_temp_variable = { famine_adapter_policy_proven = air_winter_adaptation }
				set_temp_variable = { famine_adapter_actor_proven = event_target:famine_adapter_actor.id }
				set_temp_variable = { famine_adapter_cause_proven = state_civilian_population_loss_reason }
				set_temp_variable = { famine_adapter_source_proven = air_winter_phase }
				set_temp_variable = { famine_adapter_generation = global.air_winter_cycle_id }
				set_temp_variable = { famine_adapter_revision = air_winter_population_loss_memory }
				set_temp_variable = { famine_adapter_request_id = global.date }
				famine_adapt_air_winter_state = yes
			}
		}
	}

	set_temp_variable = { chaos_deaths_change = constant:air_winter_runtime.zero }
	set_temp_variable = { chaos_deaths_is_civilian = constant:air_winter_runtime.zero }
	set_temp_variable = { chaos_deaths_apply_state_pop = constant:air_winter_runtime.zero }
	set_temp_variable = { chaos_deaths_target_country = constant:air_winter_runtime.zero }
	set_temp_variable = { chaos_deaths_has_target_country = constant:air_winter_runtime.zero }
	set_temp_variable = { chaos_deaths_reason = constant:air_winter_runtime.zero }
	set_temp_variable = { state_civilian_population_loss_applied = constant:air_winter_runtime.zero }
	set_temp_variable = { state_civilian_population_loss_result = constant:air_winter_runtime.zero }
}

black_plague_apply_current_state_mortality_once = {
	if = {
		limit = {
			black_plague_state_is_established = yes
			OR = {
				NOT = { has_variable = black_plague_last_mortality_pulse_sequence }
				NOT = {
					check_variable = {
						var = black_plague_last_mortality_pulse_sequence
						value = global.black_plague_pulse_sequence
						compare = equals
					}
				}
			}
		}
		set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_value.zero }
		if = { limit = { black_plague_state_is_incubating = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.incubating_weekly_rate } }
		else_if = { limit = { black_plague_state_is_infected = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.infected_weekly_rate } }
		else_if = { limit = { black_plague_state_is_severe = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.severe_weekly_rate } }
		else_if = { limit = { black_plague_state_is_collapsed = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.collapsed_weekly_rate } }
		else_if = { limit = { black_plague_state_is_contained = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.contained_weekly_rate } }
		else_if = { limit = { black_plague_state_is_recovering = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.recovery_weekly_rate } }
		else_if = { limit = { black_plague_state_is_rat_controlled = yes } set_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.rat_controlled_weekly_rate } }

		set_temp_variable = { black_plague_nonlinear_mortality_component = black_plague_load }
		multiply_temp_variable = { black_plague_nonlinear_mortality_component = black_plague_mortality_pressure }
		divide_temp_variable = { black_plague_nonlinear_mortality_component = constant:black_plague_value.product_scale }
		multiply_temp_variable = { black_plague_nonlinear_mortality_component = constant:black_plague_mortality.nonlinear_curve_scale }
		add_to_temp_variable = { black_plague_weekly_mortality_rate = black_plague_nonlinear_mortality_component }

		set_temp_variable = { black_plague_elapsed_mortality_component = black_plague_untreated_days }
		multiply_temp_variable = { black_plague_elapsed_mortality_component = constant:black_plague_mortality.elapsed_rate_per_day }
		clamp_temp_variable = {
			var = black_plague_elapsed_mortality_component
			min = constant:black_plague_value.zero
			max = constant:black_plague_mortality.elapsed_rate_cap
		}
		add_to_temp_variable = { black_plague_weekly_mortality_rate = black_plague_elapsed_mortality_component }

		if = {
			limit = { has_global_flag = black_plague_evolution_i_active }
			multiply_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.evolution_i_factor }
		}
		if = {
			limit = { check_variable = { black_plague_provenance = constant:black_plague_provenance.weaponized } }
			multiply_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.weaponized_factor }
		}
		else_if = {
			limit = { check_variable = { black_plague_provenance = constant:black_plague_provenance.accidental } }
			multiply_temp_variable = { black_plague_weekly_mortality_rate = constant:black_plague_mortality.accidental_factor }
		}

		set_temp_variable = { black_plague_mortality_response = black_plague_containment }
		add_to_temp_variable = { black_plague_mortality_response = black_plague_treatment_coverage }
		set_temp_variable = { black_plague_mortality_country_countermeasure = constant:black_plague_value.zero }
		CONTROLLER = {
			if = {
				limit = { has_variable = black_plague_countermeasure_progress }
				set_temp_variable = { black_plague_mortality_country_countermeasure = black_plague_countermeasure_progress }
			}
		}
		add_to_temp_variable = { black_plague_mortality_response = black_plague_mortality_country_countermeasure }
		divide_temp_variable = { black_plague_mortality_response = constant:black_plague_mortality.response_divisor }
		clamp_temp_variable = {
			var = black_plague_mortality_response
			min = constant:black_plague_value.zero
			max = constant:black_plague_mortality.maximum_response_reduction
		}
		set_temp_variable = { black_plague_mortality_response_factor = constant:black_plague_value.one }
		subtract_from_temp_variable = { black_plague_mortality_response_factor = black_plague_mortality_response }
		multiply_temp_variable = { black_plague_weekly_mortality_rate = black_plague_mortality_response_factor }
		clamp_temp_variable = {
			var = black_plague_weekly_mortality_rate
			min = constant:black_plague_value.zero
			max = constant:black_plague_mortality.maximum_weekly_rate
		}

		set_temp_variable = { black_plague_mortality_requested_people = state_population_k }
		multiply_temp_variable = { black_plague_mortality_requested_people = constant:black_plague_value.people_per_thousand }
		multiply_temp_variable = { black_plague_mortality_requested_people = black_plague_weekly_mortality_rate }
		round_temp_variable = black_plague_mortality_requested_people

		set_temp_variable = { state_civilian_population_loss_requested = black_plague_mortality_requested_people }
		set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:black_plague_mortality.nonterminal_population_floor }
		if = {
			limit = { has_global_flag = black_plague_terminal_takeover_active }
			set_temp_variable = { state_civilian_population_loss_minimum_remaining = constant:black_plague_mortality.terminal_population_floor }
		}
		set_temp_variable = { state_civilian_population_loss_reason = constant:chaos_meter_deaths_reason.black_plague }
		set_temp_variable = { state_civilian_population_loss_log_deaths = constant:black_plague_value.one }
		set_temp_variable = { state_civilian_population_loss_target_country = OWNER }
		set_temp_variable = { state_civilian_population_loss_has_target_country = constant:black_plague_value.one }
		set_temp_variable = { state_civilian_population_loss_applied = constant:black_plague_value.zero }
		set_temp_variable = { state_civilian_population_loss_result = constant:black_plague_value.zero }
		set_temp_variable = { state_civilian_population_loss_contract_supplied = constant:black_plague_value.one }
		apply_exact_state_civilian_population_loss = yes
		if = {
			limit = { check_variable = { state_civilian_population_loss_applied > 0 } }
			add_to_variable = { black_plague_deaths_applied = state_civilian_population_loss_applied }
			add_to_variable = { global.black_plague_deaths_total = state_civilian_population_loss_applied }
			# The plague pulse supplies the exact non-rat outbreak receipt. A zero
			# response or missing provenance remains represented by the positive
			# established phase rather than being invented by the adapter.
			OWNER = { save_event_target_as = famine_adapter_actor }
			set_temp_variable = { famine_adapter_state_proven = THIS.id }
			set_temp_variable = { famine_adapter_food_proven = black_plague_mortality_pressure }
			set_temp_variable = { famine_adapter_environment_proven = black_plague_load }
			set_temp_variable = { famine_adapter_transport_proven = black_plague_last_exposure_route }
			if = {
				limit = { NOT = { check_variable = { black_plague_last_exposure_route > constant:black_plague_value.zero } } }
				set_temp_variable = { famine_adapter_transport_proven = black_plague_phase }
			}
			set_temp_variable = { famine_adapter_policy_proven = black_plague_containment }
			if = {
				limit = { NOT = { check_variable = { black_plague_containment > constant:black_plague_value.zero } } }
				set_temp_variable = { famine_adapter_policy_proven = black_plague_phase }
			}
			set_temp_variable = { famine_adapter_actor_proven = event_target:famine_adapter_actor.id }
			set_temp_variable = { famine_adapter_cause_proven = state_civilian_population_loss_reason }
			set_temp_variable = { famine_adapter_source_proven = black_plague_provenance }
			if = {
				limit = { NOT = { check_variable = { black_plague_provenance > constant:black_plague_value.zero } } }
				set_temp_variable = { famine_adapter_source_proven = black_plague_phase }
			}
			set_temp_variable = { famine_adapter_generation = global.black_plague_pulse_sequence }
			if = {
				limit = { NOT = { check_variable = { global.black_plague_pulse_sequence > constant:black_plague_value.zero } } }
				set_temp_variable = { famine_adapter_generation = global.date }
			}
			set_temp_variable = { famine_adapter_revision = state_civilian_population_loss_applied }
			set_temp_variable = { famine_adapter_request_id = global.date }
			famine_adapt_black_plague_state = yes
		}
		set_variable = { black_plague_last_mortality_pulse_sequence = global.black_plague_pulse_sequence }
	}
}
